// Khaata's mark, inline so it's crisp at any size and needs no request.
// Same geometry as frontend/public/favicon.svg (generated by frontend/scripts/make_brand.py).
export function LogoMark({ size = 30, title = "Khaata" }) {
  return (
    <svg width={size} height={size} viewBox="0 0 512 512" role="img" aria-label={title} style={{ flex: "0 0 auto", display: "block" }}>
      <rect width="512" height="512" rx="116" fill="#0E7C66" />
      <g strokeWidth="66" strokeLinecap="round">
        <line x1="240" y1="236" x2="352" y2="380" stroke="#8FE3C8" />
        <line x1="178" y1="132" x2="178" y2="380" stroke="#FFFFFF" />
        <line x1="206" y1="270" x2="346" y2="132" stroke="#FFFFFF" />
      </g>
    </svg>
  );
}

// mark + name, as used in the sidebar, login and upload headers
export default function Logo({ size = 30, text = 19, onDark = false, hideText = false }) {
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: Math.round(size / 3) }}>
      <LogoMark size={size} title={hideText ? "Khaata" : ""} />
      {!hideText && (
        <span className="grotesk" style={{ fontWeight: 600, fontSize: text, letterSpacing: "-.01em",
          color: onDark ? "#f7f6f2" : "var(--ink)" }}>
          Khaata
        </span>
      )}
    </span>
  );
}
